with filtered as (select id, customer_id, device, browser, started_at, dayofweek(started_at) as started_at_dayofweek, coalesce(country, 'OTHER') as country_clean from sessions where customer_id is not null and browser in ('Firefox', 'Chrome')) select id, customer_id, device, browser, started_at_dayofweek from filtered qualify row_number() over (partition by customer_id, device order by started_at_dayofweek desc, id) = 1
